// ❌ OLD: Hand-writing a Debug (or Clone/PartialEq) impl for every
// struct is repetitive boilerplate. macro_rules! can help for simple
// repetition, but it cannot INSPECT the struct's fields the way a
// derive macro can — it only does shape-based substitution.
struct Point {
    x: i32,
    y: i32,
}

// ❌ OLD: manual impl, must be duplicated for every struct:
impl std::fmt::Debug for Point {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("Point")
            .field("x", &self.x)
            .field("y", &self.y)
            .finish()
    }
}

// And Clone, PartialEq, Eq, Hash... each written by hand.

// ✅ NEW: #[derive] is a procedural macro that PARSES the struct's
// AST, inspects each field, and GENERATES the impl. No boilerplate.
#[derive(Debug, Clone, PartialEq, Eq)] // ✅ NEW: generated impls
struct Point {
    x: i32,
    y: i32,
}

